CREATE DATABASE IF NOT EXISTS signflow CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE signflow;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('employee','head','admin') NOT NULL,department VARCHAR(120) NOT NULL,signature_path VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS documents (id INT AUTO_INCREMENT PRIMARY KEY,reference VARCHAR(40) UNIQUE,employee_id INT NOT NULL,head_id INT NOT NULL,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,original_pdf VARCHAR(255) NULL,original_name VARCHAR(255) NULL,status ENUM('draft','pending','returned','rejected','approved') NOT NULL DEFAULT 'draft',version INT NOT NULL DEFAULT 1,employee_signed_at DATETIME NULL,head_signed_at DATETIME NULL,final_pdf VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(employee_id) REFERENCES users(id),FOREIGN KEY(head_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS signatures (id INT AUTO_INCREMENT PRIMARY KEY,document_id INT NOT NULL,user_id INT NOT NULL,version INT NOT NULL,kind ENUM('employee','head') NOT NULL,file_path VARCHAR(255) NOT NULL,page_num INT NOT NULL DEFAULT 1,x_pct DECIMAL(7,4) NOT NULL DEFAULT 10,y_pct DECIMAL(7,4) NOT NULL DEFAULT 75,width_pct DECIMAL(7,4) NOT NULL DEFAULT 28,height_pct DECIMAL(7,4) NOT NULL DEFAULT 10,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(document_id) REFERENCES documents(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS approval_history (id INT AUTO_INCREMENT PRIMARY KEY,document_id INT NOT NULL,actor_id INT NOT NULL,action VARCHAR(40) NOT NULL,remarks TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(document_id) REFERENCES documents(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,document_id INT NOT NULL,subject VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,read_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(document_id) REFERENCES documents(id));
CREATE TABLE IF NOT EXISTS email_logs (id INT AUTO_INCREMENT PRIMARY KEY,document_id INT NOT NULL,user_id INT NOT NULL,event_key VARCHAR(80) NOT NULL,status ENUM('sent','failed','disabled') NOT NULL,details TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(document_id,event_key,created_at));
